// Validate + Normalize (Run once for each item)

const src = $json;

// 1) Find the real payload root (sometimes it’s nested)
const body =
  (src && typeof src === "object" && !Array.isArray(src) && (src.body || src.data))
    ? (src.body || src.data)
    : src;

function asStr(x) {
  return (x === null || x === undefined) ? "" : String(x);
}

function tryParseJson(x) {
  if (typeof x !== "string") return x;
  const s = x.trim();
  if (!s) return x;
  if (!(s.startsWith("{") || s.startsWith("["))) return x;
  try { return JSON.parse(s); } catch { return x; }
}

function asArrayFlexible(x) {
  x = tryParseJson(x);

  if (Array.isArray(x)) return x;

  // If n8n gives { "0": {...}, "1": {...} }
  if (x && typeof x === "object") {
    const vals = Object.values(x);
    // Only accept if it looks like an array-ish object
    if (vals.length && typeof vals[0] === "object") return vals;
  }

  return [];
}

const cvVersionId = asStr(body.cvVersionId).trim() || null;
const cvTitle     = asStr(body.cvTitle).trim();
const targetRole  = asStr(body.targetRole).trim();
const language    = (asStr(body.language).toLowerCase() === "en") ? "en" : "sv";

const modeRaw     = asStr(body.mode).toLowerCase();
const mode        = ["chat","blocks","full"].includes(modeRaw) ? modeRaw : "chat";

const message     = asStr(body.message).trim();

// IMPORTANT: flexible array decode
const blocksRaw   = body.blocks;
const blocks      = asArrayFlexible(blocksRaw);

const historyRaw  = body.history;
const historyArr  = asArrayFlexible(historyRaw);

const history = historyArr.slice(-12).map(m => ({
  role: m?.role === "user" ? "user" : "assistant",
  content: asStr(m?.content).trim()
})).filter(m => m.content);

// selected ids
const selectedInRaw = body.selectedBlockIds;
const selectedInArr = asArrayFlexible(selectedInRaw).map(String);

const validBlockIds = new Set(
  blocks.map(b => String(b?.blockId || b?.blockID || b?.id || ""))
);

const selectedBlockIds = selectedInArr.filter(id => validBlockIds.has(id));

return {
  json: {
    // Carry-through to avoid losing fields via Merge / node output shape changes
    ...src,
    ...body,

    // Canonical fields (what downstream should rely on)
    cvVersionId,
    cvTitle,
    targetRole,
    language,
    mode,
    message,
    blocks,
    history,
    selectedBlockIds,

    // Debug so you can SEE what happened
    _debug: {
      ...(body._debug || src._debug || {}),
      blocksType: typeof blocksRaw,
      blocksIsArray: Array.isArray(blocksRaw),
      blocksLen: blocks.length,
      selectedInLen: selectedInArr.length,
      selectedKeptLen: selectedBlockIds.length,
      _peek: {
        srcKeys: Object.keys(src || {}),
        bodyKeys: Object.keys(body || {}),
        hasBodyWrapper: !!(src && (src.body || src.data)),
        modeRaw,
      }
    }
  }
};

// Build LLM Messages (preserve blocks + other webhook fields)

const input = $json;

function asArr(x) { return Array.isArray(x) ? x : []; }
function asStr(x) { return (x === null || x === undefined) ? "" : String(x); }

function pickBlocks(blocks, ids) {
  const idSet = new Set(asArr(ids).map(String));
  return asArr(blocks).filter(b => idSet.has(String(b?.blockId || "")));
}

function trimText(s, max = 700) {
  const t = asStr(s).replace(/\s+/g, " ").trim();
  if (t.length <= max) return t;
  return t.slice(0, max) + "…";
}

function utf8Bytes(str) {
  return new TextEncoder().encode(String(str || "")).length;
}

const userMsgRaw = asStr(input.message).trim();
const isPing = /^\/ping\b/i.test(userMsgRaw);

// Normalize critical fields and ALWAYS preserve blocks
const blocks = asArr(input.blocks);
const selectedBlockIds = asArr(input.selectedBlockIds).map(String);
const history = asArr(input.history);

// Decide mode
const mode =
  (selectedBlockIds.length > 0) ? "blocks" :
  (asStr(input.mode).toLowerCase() === "full") ? "full" :
  "chat";

// Build context blocks
let contextBlocks = [];
if (mode === "blocks") contextBlocks = pickBlocks(blocks, selectedBlockIds);
else if (mode === "full") contextBlocks = blocks;
else contextBlocks = [];

// Trim context
const trimmedContextBlocks = contextBlocks.map(b => ({
  blockId: asStr(b.blockId),
  type: asStr(b.type),
  label: asStr(b.label),

  title: asStr(b.title),
  employer: asStr(b.employer),
  startDate: asStr(b.startDate),
  endDate: asStr(b.endDate),
  institution: asStr(b.institution),
  degree: asStr(b.degree),
  program: asStr(b.program),

  textExcerpt: trimText(b.text, 700)
}));

// Limit history hard
const historyLines = history
  .slice(-6)
  .map(h => `${(h?.role || "assistant").toUpperCase()}: ${(h?.content || "").trim()}`)
  .filter(Boolean)
  .join("\n");

// Output schemas
const schemaAnswer = {
  ok: true,
  intent: "answer",
  assistantMessage: "string",
  suggestion: null
};

const schemaSuggestion = {
  ok: true,
  intent: "suggestion",
  assistantMessage: "string",
  suggestion: {
    mode: "blocks|full",
    selectedBlockIds: ["blockId"],
    instruction: "string"
  }
};

// ====== PING MODE ======
if (isPing) {
  const promptTextPing =
`Return ONLY valid JSON (no markdown, no extra text) exactly like this:
{"ok":true,"intent":"answer","assistantMessage":"pong","suggestion":null}
`;

  const promptKb = Math.round(utf8Bytes(promptTextPing) / 1024);

  return {
    json: {
      ...input,
      mode,
      message: userMsgRaw,
      blocks,
      selectedBlockIds,
      history,
      promptText: promptTextPing,
      _debug: {
        ...(input._debug || {}),
        benchmarkMode: "ping",
        promptKb,
        promptChars: promptTextPing.length,
        hasBlocks: true,
        blocksLen: blocks.length
      }
    }
  };
}

// ====== NORMAL MODE ======
const system = `
You are Drafted Chat, a CV editing assistant.

Your job in THIS flow:
- Answer the user's question.
- Optionally propose a rewrite suggestion as an INSTRUCTION only.
- DO NOT rewrite the CV here. DO NOT output full blocks. No patching.

Return ONLY valid JSON. No markdown. No extra text.

DECISION RULE:
- If mode is "blocks" or "full" AND the user asks whether they SHOULD change the CV, how to structure, or requests improvements:
  -> intent MUST be "suggestion" and suggestion must be provided.
- If mode is "chat":
  -> intent MUST be "answer" and suggestion MUST be null.

If intent="suggestion":
- suggestion.instruction must be a short actionable instruction suitable for a rewrite pipeline
- suggestion.mode must be "blocks" when selectedBlockIds is non-empty, otherwise "full"
- suggestion.selectedBlockIds must be the selected ids when mode="blocks", otherwise []

Output must match exactly ONE of these examples:
ANSWER:
${JSON.stringify(schemaAnswer)}
SUGGESTION:
${JSON.stringify(schemaSuggestion)}
`.trim();

// NEW: broader detection for "should I..." questions that imply a change
const looksLikeChangeRequest =
  // direct change verbs
  /\b(ändra|förbättra|skriv om|omformulera|kortare|längre|mer|mindre|ta bort|lägg till|strukturera|omstrukturera|prioritera|förtydliga|förenkla)\b/i.test(userMsgRaw) ||
  // split/group/organize language
  /\b(dela upp|slå ihop|gruppera|kategorisera|sortera|rubriker|underrubriker|sektion)\b/i.test(userMsgRaw) ||
  // "should I" pattern (Swedish)
  /^\s*(borde jag|ska jag|bör jag|är det bättre att|tycker du att jag ska|kan det vara bra att)\b/i.test(userMsgRaw);

// Hard rule: if we have selected blocks and user is asking a "should" question, force suggestion
const shouldForceSuggestion = (mode === "blocks" || mode === "full") && looksLikeChangeRequest;

const payloadForModel = {
  language: asStr(input.language || "sv"),
  targetRole: asStr(input.targetRole || ""),
  mode,
  selectedBlockIds: mode === "blocks" ? selectedBlockIds : [],
  userMessage: userMsgRaw,
  hint: {
    looksLikeChangeRequest,
    shouldForceSuggestion
  },
  cvTitle: asStr(input.cvTitle || ""),
  contextBlocks: trimmedContextBlocks
};

const promptText =
`${system}

Conversation so far:
${historyLines || "(none)"}

New request (JSON):
${JSON.stringify(payloadForModel)}
`;

const promptKb = Math.round(utf8Bytes(promptText) / 1024);

return {
  json: {
    ...input,
    mode,
    message: userMsgRaw,
    blocks,
    selectedBlockIds,
    history,
    promptText,
    _debug: {
      ...(input._debug || {}),
      benchmarkMode: "normal",
      promptKb,
      promptChars: promptText.length,
      historyCount: history.length,
      sentHistoryCount: Math.min(history.length, 6),
      contextBlocksCount: trimmedContextBlocks.length,
      mode,
      hasBlocks: true,
      blocksLen: blocks.length,
      looksLikeChangeRequest,
      shouldForceSuggestion
    }
  }
};

const input = $json;

function asArr(x) { return Array.isArray(x) ? x : []; }
function asStr(x) { return (x === null || x === undefined) ? "" : String(x); }

function sanitizeLeadingGarbage(str) {
  return String(str || "")
    .replace(/^\uFEFF/, "")
    .replace(/^=+/, "")
    .trim();
}

function extractModelText(json) {
  // n8n OpenAI node shapes vary
  const t1 = json?.output?.[0]?.content?.[0]?.text;
  if (t1) return asStr(t1);

  if (json?.text) return asStr(json.text);
  if (json?.content) return asStr(json.content);

  // Some nodes put it here:
  const t2 = json?.data?.output?.[0]?.content?.[0]?.text;
  if (t2) return asStr(t2);

  // Fallback
  try { return JSON.stringify(json); } catch { return asStr(json); }
}

// Note: chat can run with blocks present or not. We must not leak debug/meta.
const blocks = asArr(input.blocks);
const hasBlocks = Array.isArray(blocks) && blocks.length > 0;

const rawModel = extractModelText(input);
const modelText = sanitizeLeadingGarbage(rawModel);

let parsed = null;
let parseOk = false;

try {
  parsed = JSON.parse(modelText);
  parseOk = true;
} catch (e) {
  parsed = null;
}

// Model output normalization
const intentRaw = asStr(parsed?.intent || "answer").toLowerCase();
const assistantText = asStr(parsed?.assistantMessage || parsed?.message || "").trim() || "Okay.";

// Support both legacy proposal + new suggestion (optional)
const suggestion =
  (parsed?.suggestion && typeof parsed.suggestion === "object" && !Array.isArray(parsed.suggestion))
    ? parsed.suggestion
    : null;

const proposal =
  (parsed?.proposal && typeof parsed.proposal === "object" && !Array.isArray(parsed.proposal))
    ? parsed.proposal
    : null;

// If model suggested something but we have no blocks, degrade to answer (still ok=true)
let finalIntent = intentRaw;
let finalSuggestion = suggestion;

if ((intentRaw === "suggestion" || intentRaw === "proposal") && !hasBlocks) {
  finalIntent = "answer";
  finalSuggestion = null;
}

// Build minimal public response contract for chat
// IMPORTANT: response.message is ALWAYS the assistant output (request.message is user input).
const out = {
  ok: true,
  message: assistantText,
};

// Optional metadata fields (only include when present/valid)
if (finalIntent) out.intent = finalIntent;
if (proposal !== null) out.proposal = proposal;
if (finalSuggestion !== null) out.suggestion = finalSuggestion;

const changedBlockIds = asArr(input.changedBlockIds);
if (changedBlockIds.length > 0) out.changedBlockIds = changedBlockIds;

// Never include _debug in production response contract.
// If you need debug, log it in node execution or keep it internal.
// (parseOk is intentionally not returned)
return { json: out };
